class Solution:
    def minMoves(self, classroom: List[str], energy: int) -> int:
        m, n = len(classroom), len(classroom[0])
        litter = {}
        for r in range(m):
            for c in range(n):
                if classroom[r][c] == "S":
                    start = (r, c)
                elif classroom[r][c] == "L":
                    litter[(r, c)] = len(litter)       # one mask bit per litter cell
        full = (1 << len(litter)) - 1
        # best[r][c][mask] = highest energy seen at that state; lower energy is dominated
        best = [[[-1] * (full + 1) for _ in range(n)] for _ in range(m)]
        best[start[0]][start[1]][0] = energy
        queue = deque([(start[0], start[1], 0, energy, 0)])
        while queue:
            r, c, mask, e, steps = queue.popleft()
            if mask == full:
                return steps
            if e == 0:
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < m and 0 <= nc < n) or classroom[nr][nc] == "X":
                    continue
                ne, nmask = e - 1, mask
                if classroom[nr][nc] == "R":
                    ne = energy
                elif classroom[nr][nc] == "L":
                    nmask |= 1 << litter[(nr, nc)]
                if ne > best[nr][nc][nmask]:
                    best[nr][nc][nmask] = ne
                    queue.append((nr, nc, nmask, ne, steps + 1))
        return -1
